 353|     }
 354|   }
 355|   
 356|   bne(rs, rt, offset) {
 357|     // BNE rs,rt,offset - Branch on Not Equal
 358|     if (this.registers[rs] !== this.registers[rt]) {
 359|       this.pc = (this.pc + (offset << 2)) >>> 0;
 360|     }
 361|   }
 362|   
 363|   // ---- Jump Operations ----
 364|   
 365|   j(target) {
 366|     // J target - Jump
 367|     // Combine upper 4 bits of PC with 26-bit target shifted left by 2
 368|     this.pc = ((this.pc & 0xF0000000) | (target << 2)) >>> 0;
 369|   }
 370|   
 371|   jal(target) {
