25| typedef struct
26| {
27|     wad_file_t wad;
28|     FILE *fstream;
29| } stdc_wad_file_t;
30| 
31| extern wad_file_class_t stdc_wad_file;
32| 
33| static wad_file_t *W_StdC_OpenFile(char *path)
34| {
35|     stdc_wad_file_t *result;
36|     FILE *fstream;
37| 
38|     fstream = fopen(path, "rb");
39| 
40|     if (fstream == NULL)
41|     {
42|         return NULL;
43|     }
44| 
45|     // Create a new stdc_wad_file_t to hold the file handle.
46| 
47|     result = Z_Malloc(sizeof(stdc_wad_file_t), PU_STATIC, 0);
48|     result->wad.file_class = &stdc_wad_file;
49|     result->wad.mapped = NULL;
50|     result->wad.length = M_FileLength(fstream);
51|     result->fstream = fstream;
52| 
53|     return &result->wad;
54| }
55| 
56| static void W_StdC_CloseFile(wad_file_t *wad)
57| {
58|     stdc_wad_file_t *stdc_wad;
59| 
60|     stdc_wad = (stdc_wad_file_t *) wad;
61| 
62|     fclose(stdc_wad->fstream);
63|     Z_Free(stdc_wad);
64| }
65| 
66| // Read data from the specified position in the file into the 
67| // provided buffer.  Returns the number of bytes read.
68| 
69| size_t W_StdC_Read(wad_file_t *wad, unsigned int offset,
70|                    void *buffer, size_t buffer_len)
71| {
72|     stdc_wad_file_t *stdc_wad;
73|     size_t result;
74| 
75|     stdc_wad = (stdc_wad_file_t *) wad;
76| 
77|     // Jump to the specified position in the file.
78| 
79|     fseek(stdc_wad->fstream, offset, SEEK_SET);
80| 
81|     // Read into the buffer.
82| 
83|     result = fread(buffer, 1, buffer_len, stdc_wad->fstream);
84| 
85|     return result;
86| }
87| 
88| 
