 133| byte *I_ZoneBase (int *size)
 134| {
 135|     byte *zonemem;
 136|     int min_ram, default_ram;
 137|     int p;
 138| 
 139|     //!
 140|     // @arg <mb>
 141|     //
 142|     // Specify the heap size, in MiB (default 16).
 143|     //
 144| 
 145|     p = M_CheckParmWithArgs("-mb", 1);
 146| 
 147|     if (p > 0)
 148|     {
 149|         default_ram = atoi(myargv[p+1]);
 150|         min_ram = default_ram;
 151|     }
 152|     else
 153|     {
 154|         default_ram = DEFAULT_RAM;
 155|         min_ram = MIN_RAM;
 156|     }
 157| 
 158|     zonemem = AutoAllocMemory(size, default_ram, min_ram);
 159| 
 160|     printf("zone memory: %p, %x allocated for zone\n", 
 161|            zonemem, *size);
 162| 
 163|     return zonemem;
 164| }
