#include <stdint.h>
#include <stddef.h>

static int runtime_errno;

int *__errno_location(void)
{
    return &runtime_errno;
}

static unsigned short ctype_bits[384];
static int32_t ctype_lower[384];
static int32_t ctype_upper[384];
static int ctype_ready;

static void init_ctype(void)
{
    int i;
    if (ctype_ready)
        return;
    ctype_ready = 1;
    for (i = 0; i < 384; ++i) {
        ctype_lower[i] = i - 128;
        ctype_upper[i] = i - 128;
    }
    for (i = 0; i < 256; ++i) {
        int c = i;
        unsigned short bits = 0;
        if (c >= 'A' && c <= 'Z') {
            bits |= 0x0100 | 0x0400 | 0x4000 | 0x8000;
            ctype_lower[c + 128] = c + ('a' - 'A');
        }
        if (c >= 'a' && c <= 'z') {
            bits |= 0x0200 | 0x0400 | 0x4000 | 0x8000;
            ctype_upper[c + 128] = c - ('a' - 'A');
        }
        if (c >= '0' && c <= '9')
            bits |= 0x0800 | 0x1000 | 0x8000;
        if ((c >= '0' && c <= '9') ||
            (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f'))
            bits |= 0x1000;
        if (c == ' ' || c == '\t')
            bits |= 0x0080 | 0x2000 | 0x4000;
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r' ||
            c == '\f' || c == '\v')
            bits |= 0x2000;
        if (c >= 0x20 && c <= 0x7e)
            bits |= 0x4000;
        if (c >= 0x21 && c <= 0x7e)
            bits |= 0x8000;
        if (c < 0x20 || c == 0x7f)
            bits |= 0x0080;
        if (c >= 0x21 && c <= 0x2f)
            bits |= 0x0400;
        if (c >= 0x3a && c <= 0x40)
            bits |= 0x0400;
        if (c >= 0x5b && c <= 0x60)
            bits |= 0x0400;
        if (c >= 0x7b && c <= 0x7e)
            bits |= 0x0400;
        ctype_bits[c + 128] = bits;
    }
}

const unsigned short int **__ctype_b_loc(void)
{
    static const unsigned short int *p;
    init_ctype();
    p = ctype_bits + 128;
    return &p;
}

const int32_t **__ctype_tolower_loc(void)
{
    static const int32_t *p;
    init_ctype();
    p = ctype_lower + 128;
    return &p;
}

const int32_t **__ctype_toupper_loc(void)
{
    static const int32_t *p;
    init_ctype();
    p = ctype_upper + 128;
    return &p;
}

void __ctype_init(void)
{
    init_ctype();
}

int atexit(void (*function)(void))
{
    (void) function;
    return 0;
}

int __cxa_atexit(void (*function)(void *), void *arg, void *dso_handle)
{
    (void) function;
    (void) arg;
    (void) dso_handle;
    return 0;
}

__attribute__((noreturn)) void exit(int status)
{
    (void) status;
    for (;;)
        __asm__ volatile ("" ::: "memory");
}

__attribute__((noreturn)) void _exit(int status)
{
    (void) status;
    for (;;)
        __asm__ volatile ("" ::: "memory");
}

