        int precision = -1;
        int zero_pad = 0;
        int long_arg = 0;
        int size_arg = 0;
        if (*format != '%') {
            append_char(buffer, capacity, &used, *format++);
            continue;
        }
        ++format;
        if (*format == '%') {
            append_char(buffer, capacity, &used, *format++);
